using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.Player;using Rootborn.UI.Modern;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryItemPresentationTests{
[TestCase("ko","Allowance","용돈","수량: 12")][TestCase("en","Allowance","Allowance","Count: 12")][TestCase("ko","FacilityMaterials","시설 보수 자재","수량: 12")][TestCase("en","FacilityMaterials","Renovation materials","Count: 12")]public void ActualItemPopupUsesLocalizedTitleCountAndFittedTitle(string lang,string file,string title,string count){string beforeLang=GameText.Language;var root=new GameObject("Inventory",typeof(RectTransform));var player=new GameObject("Fixture",typeof(PlayerInventory));var item=AssetDatabase.LoadAssetAtPath<ItemDefinition>("Assets/Data/Items/Item_"+file+".asset");var before=EditorJsonUtility.ToJson(item);try{GameDataRegistryProvider.SetOverrideForTests(AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset"));GameText.Language=lang;var inv=player.GetComponent<PlayerInventory>();inv.Inventory.Add(item,12);var panel=root.AddComponent<ModernUiInventoryPanel>();panel.Bind(inv);panel.Show();root.GetComponentsInChildren<ScrollRect>().Single().content.GetChild(0).GetComponent<Button>().onClick.Invoke();var popup=root.transform.Find("ItemDetailPopup");var label=popup.Find("ItemName").GetComponent<Text>();Assert.That(label.text,Is.EqualTo(title));Assert.That(popup.Find("ItemCount").GetComponent<Text>().text,Is.EqualTo(count));Assert.That(label.resizeTextForBestFit,Is.True);Assert.That(label.resizeTextMinSize,Is.GreaterThanOrEqualTo(24));Assert.That(EditorJsonUtility.ToJson(item),Is.EqualTo(before));Assert.That(inv.Inventory.CountOf(item),Is.EqualTo(12));}finally{Object.DestroyImmediate(root);Object.DestroyImmediate(player);GameText.Language=beforeLang;GameDataRegistryProvider.ClearOverrideForTests();GameDataRegistryProvider.ResetCacheForTests();}}
}}
